from math import comb

def relational_fraction(n: int, k: int) -> float:
    intrinsic = k * comb(n, 2)
    cross = comb(k, 2) * n * n
    return cross / (intrinsic + cross)

for k in [2, 5, 10, 100, 1000]:
    print(k, round(relational_fraction(1000, k), 4),
          round(1 - 1 / k, 4))

