from math import comb, floor

def max_log2_weight(n: int, bit_budget: float) -> float:
    slots: int = comb(n, 2)
    if slots == 0:
        return float('inf')
    return bit_budget / slots

def optimal_alphabet(n: int, bit_budget: float) -> float:
    e = max_log2_weight(n, bit_budget)
    return 2.0 ** e if e < 60 else float('inf')
